(function(){
  var SH = Java.loadClass('net.neoforged.neoforge.server.ServerLifecycleHooks');
  var s = SH.getCurrentServer();
  if (s === null) { return { ok: false, reason: 'no-server' }; }
  var list = s.getPlayerList().getPlayers();
  if (list.size() === 0) { return { ok: false, reason: 'no-player' }; }
  var p = list.get(0);
  var Reg = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
  var RL = Java.loadClass('net.minecraft.resources.ResourceLocation');
  var IS = Java.loadClass('net.minecraft.world.item.ItemStack');
  var CuriosApi = Java.loadClass('top.theillusivec4.curios.api.CuriosApi');
  var Dorothy = Java.loadClass('com.merlinkitsune.astral_dice.item.sign.DorothySignItem');
  var Jill = Java.loadClass('com.merlinkitsune.astral_dice.item.sign.JillSignItem');
  var Effects = Java.loadClass('com.merlinkitsune.astral_dice.effect.ModEffects');
  var Removal = Java.loadClass('com.merlinkitsune.starengine.event.ModEffectRemoval');
  try { Removal.remove(p, Effects.DOROTHY_WARMTH); } catch (e) { }
  p.setHealth(6.0);
  var curios = CuriosApi.getCuriosInventory(p).get();
  var stand = curios.getStacksHandler('stand').get().getStacks();
  stand.setStackInSlot(0, new IS(Reg.ITEM.get(RL.parse('astral_dice:dorothy_sign'))));
  var dice = curios.getStacksHandler('dice').get().getStacks();
  dice.setStackInSlot(0, new IS(Reg.ITEM.get(RL.parse('astral_dice:golden_dice'))));
  var item = Reg.ITEM.get(RL.parse('astral_dice:effect_card_monster_laser'));
  var inv = p.getInventory();
  for (var i = 0; i < 3; i++) { inv.add(new IS(item)); }
  return {
    ok: true,
    name: p.getName().getString(),
    hp0: p.getHealth(),
    max: p.getMaxHealth(),
    warmth0: Dorothy.warmthStacks(p),
    equipped: Dorothy.isEquippedForWarmth(p),
    stand: String(Reg.ITEM.getKey(stand.getStackInSlot(0).getItem())),
    dice: String(Reg.ITEM.getKey(dice.getStackInSlot(0).getItem())),
    cards: Jill.countCards(p)
  };
})()

(function(){
  var SH = Java.loadClass('net.neoforged.neoforge.server.ServerLifecycleHooks');
  var s = SH.getCurrentServer();
  if (s === null) { return { ok: false, reason: 'no-server' }; }
  var p = s.getPlayerList().getPlayers().get(0);
  var Reg = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
  var RL = Java.loadClass('net.minecraft.resources.ResourceLocation');
  var IS = Java.loadClass('net.minecraft.world.item.ItemStack');
  var TSM = Java.loadClass('com.merlinkitsune.astral_dice.target.TargetSelectionManager');
  var CCM = Java.loadClass('com.merlinkitsune.astral_dice.choice.CardChoiceManager');
  var Att = Java.loadClass('com.merlinkitsune.astral_dice.component.ModAttachments');
  var Dorothy = Java.loadClass('com.merlinkitsune.astral_dice.item.sign.DorothySignItem');
  var Jill = Java.loadClass('com.merlinkitsune.astral_dice.item.sign.JillSignItem');
  var out = { ok: false, label: 'dorothy-equipped-3effect' };
  out.hpBefore = p.getHealth();
  out.warmthBefore = Dorothy.warmthStacks(p);
  out.cardsBefore = Jill.countCards(p);
  var started = TSM.start(p, 'astral_dice:jill_mix');
  out.started = started;
  if (!started) { out.reason = 'start-failed'; return out; }
  var tok = TSM.sessionTokenForTests(p);
  out.selToken = tok;
  TSM.confirm(p, tok, p.getId());
  var menu = p.containerMenu;
  out.menuToken = -1;
  try { out.menuToken = menu.token(); } catch (e) { out.menuErr = ('' + e).substring(0, 80); }
  var item = Reg.ITEM.get(RL.parse('astral_dice:effect_card_monster_laser'));
  var filled = 0;
  for (var i = 0; i < 3; i++) {
    try { menu.getSlot(i).set(new IS(item)); filled++; } catch (e2) { out.fillErr = ('' + e2).substring(0, 80); }
  }
  out.filled = filled;
  out.filledSlots = -1;
  try { out.filledSlots = menu.filledSlots(); } catch (e3) { }
  out.pendingBefore = String(Att.getJillPendingTarget(p)).length > 0;
  if (out.menuToken > 0) { CCM.confirm(p, out.menuToken); }
  out.pendingAfter = String(Att.getJillPendingTarget(p));
  out.hp = p.getHealth();
  out.warmth = Dorothy.warmthStacks(p);
  out.equipped = Dorothy.isEquippedForWarmth(p);
  out.cardsAfter = Jill.countCards(p);
  out.ok = (out.filledSlots === 3) && (String(out.pendingAfter).length === 0) && (out.hp !== out.hpBefore);
  return out;
})()

